function dateText(value){if(typeof value!=='string'||!value)return'未提供';const date=new Date(value);return Number.isNaN(date.getTime())?'未提供':new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(date);}
function rating(value){return Number.isInteger(value)&&value>=1&&value<=5?'个人评分 '+value+' / 5':'未评分';}
function workDetails(item){return item?.details&&typeof item.details==='object'&&!Array.isArray(item.details)?item.details:{};}
function workRating(details){return typeof details.doubanRating==='number'&&Number.isFinite(details.doubanRating)&&details.doubanRating>=0&&details.doubanRating<=10?details.doubanRating.toFixed(1)+' / 10':null;}
function workYear(details){return Number.isInteger(details.year)&&details.year>=1&&details.year<=2100?String(details.year):null;}
function detailText(value){return typeof value==='string'&&value.trim()?value.trim():null;}
