function profileStatus(message,error=false){el('profile-status').textContent=message||'';el('profile-status').classList.toggle('error',error);if(error)openTools('manage');updateWorkspace();}
function mutationLocked(){return resetState.busy||Boolean(resetState.pending)||Boolean(browserSync?.isLocked())||changedAccount()||state.profileBusy||state.syncing||metadataState.busy||Boolean(metadataState.pending)||Boolean(personalUI?.isBusy())||Boolean(coverUI?.isBusy())||state.detailBusy||importState.busy||Boolean(importState.pending);}
